	team := Team{Members: []Member{{SessionIDs: []string{"mapped"}}}}
	filtered := filterMappedCheckpoints(team, checkpoints)
	if len(filtered) != 1 || filtered[0].ID != "commit" {
		t.Fatalf("checkpoints = %#v", filtered)
	}
}

