   520			From: index.endpoints[current], To: index.endpoints[edge.next], Relation: edge.relation.Type,
   521			Direction: direction, Confidence: edge.relation.Confidence, Resolution: edge.relation.Resolution,
   522			Reason: edge.relation.Reason,
   523		}
   524		for _, evidence := range edge.relation.Evidence {
   525			step.Evidence = append(step.Evidence, Evidence{Kind: evidence.Kind, File: evidence.FilePath, StartLine: evidence.StartLine, EndLine: evidence.EndLine, Detail: evidence.Detail})
   526		}
   527		return step
   528	}
