   535		case "IMPORTS", "CALLS", "CONSTRUCTS", "ASYNC_CALLS", "USES_TYPE", "PARAM_TYPE", "RETURNS_TYPE",
   536			"READS_FIELD", "WRITES_FIELD", "ACCESSES", "DATA_FLOWS", "RESOURCE_DEPENDS_ON":
