   547		}
   548		for id := range right {
   549			all[id] = true
   550		}
   551		tests := map[string]bool{}
   552		for _, relation := range index.relations {
   553			if relation.Type != "TESTS" || !all[relation.FromID] && !all[relation.ToID] {
