   555			}
   556			for _, id := range []string{relation.FromID, relation.ToID} {
   557				if endpoint, ok := index.endpoints[id]; ok && conventionalTestPath(endpoint.File) {
   558					tests[endpoint.File] = true
   559				}
   560			}
   561		}
   562		var result []string
   563		for path := range tests {
   564			result = append(result, path)
   565		}
   566		sort.Strings(result)
   567		return result
   568	}
