   574			strings.Contains(lower, "/__tests__/") || strings.HasSuffix(base, "_test.go") ||
   575			strings.HasSuffix(base, "_test.py") || strings.HasPrefix(base, "test_") ||
   576			strings.Contains(base, ".test.") || strings.Contains(base, ".spec.")
   577	}
