     5	// moduleKind labels a synthetic entity that represents file/module scope: code
     6	// that lives outside any named symbol (top-level statements, imports, comments).
     7	// Changes attributed to it keep module-scope edits visible in the diff instead
     8	// of being dropped as null.
     9	const moduleKind = "module"
    10	
    11	type Entity struct {
    12		Kind        string `json:"kind"`
    13		Name        string `json:"name"`
    14		Signature   string `json:"signature"`
    15		StartLine   int    `json:"start_line"`
    16		EndLine     int    `json:"end_line"`
    17		BodyHash    string `json:"body_hash"`
    18		Fingerprint string `json:"fingerprint"`
    19		// Local marks a callable defined inside another function (a nested/closure
    20		// def). It is still a real symbol, but it is only callable from within its
    21		// enclosing function, so call resolution must not name-match it across scopes.
    22		Local bool `json:"-"`
    23		// bodyless marks a declaration that declares a callable without defining it:
    24		// a TypeScript overload signature or an ambient `declare function`. It is a
    25		// real symbol (the declared types live only there), but it is NOT a second
    26		// definition of the name — the implementation right below it is. Two rules
    27		// depend on the distinction: the implementation must keep the bare
    28		// compound-v1 symbol ID no matter how many signatures precede it, and a call
    29		// that lands on an overload set must resolve to the implementation instead of
    30		// being downgraded as ambiguous. Private, like the other parse metadata, so
    31		// the frozen schema is unchanged.
    32		bodyless bool
    33		// cLinkage marks a declaration that sits inside an `extern "C" { ... }`
    34		// block (see declaredWithCLinkage). It is the only per-declaration record of
    35		// which half of a dual-use C++-labelled header a C translation unit may
    36		// name. Private, like the other parse metadata, so the frozen schema and the
    37		// compound-v1 IDs are unchanged.
    38		cLinkage bool
    39		// sourceStartByte/sourceEndByte are the exact tree-sitter declaration range.
    40		// They are internal parse metadata: public schema and stable symbol identity
    41		// intentionally remain line based. A zero start is valid when end > start.
    42		sourceStartByte int
    43		sourceEndByte   int
    44		// parameterNames holds JS/TS parameter identifiers read from the
    45		// declaration's formal_parameters AST node (internal parse metadata, like
    46		// the byte range). Signature-string parsing cannot recover these reliably:
    47		// generic clauses may themselves contain parenthesized function types.
    48		parameterNames      []string
    49		parameterNamesKnown bool
    50		// paramTypeText/returnTypeText hold the callable's declared types as the
    51		// parse tree delimits them, so the type passes do not have to re-guess
    52		// where a signature's parameter list ends. signatureTypesKnown separates
    53		// "the grammar says this callable declares no return type" from "no parser
    54		// metadata"; both stay private to preserve the frozen schema.
    55		paramTypeText       string
    56		returnTypeText      string
    57		signatureTypesKnown bool
    58	}
    59	
    60	type EntityChange struct {
    61		Type            string  `json:"type"`
