   497			decision.Recommendations = []string{"Assign the symbol to one mission, or sequence the missions before editing."}
   498			decision.Verification = []string{"Verify the mission assignments against the plan before editing."}
   499			return decision
   500		}
   501		if overlap := firstOverlap(left.files, right.files); overlap != "" {
   502			endpoint := Endpoint{Name: overlap, Kind: "file", File: overlap}
   503			if file, ok := index.filesByPath[overlap]; ok {
   504				endpoint.ID = file.ID
   505			}
   506			decision.Level, decision.Reason = "BLOCK", "same file is assigned to both missions"
   507			decision.Path = []Step{{From: endpoint, To: endpoint, Relation: "SAME_FILE", Direction: "shared", Confidence: 1, EvidenceClass: "confirmed"}}
   508			decision.EvidenceClass = "confirmed"
   509			decision.Recommendations = []string{"Assign the file to one mission, or sequence the missions before editing."}
   510			decision.Verification = []string{"Verify the mission assignments against the plan before editing."}
   511			return decision
   512		}
   513		path := index.shortestPath(left.endpoints, right.endpoints, 2)
