   516			decision.EvidenceClass = "incomplete"
   517			decision.VerificationRequired = true
   518			decision.Recommendations = []string{"Proceed in parallel, while treating this bounded static analysis as advisory."}
   519			decision.Verification = []string{"Inspect the source for runtime wiring, generated code, reflection, or dynamic dispatch, then run focused tests for both mission targets."}
