   614			EvidenceClass: relationEvidenceClass(edge.relation), Reason: edge.relation.Reason,
   615			WarningCodes: append([]string(nil), edge.relation.WarningCodes...), EvidenceDropped: edge.relation.EvidenceDropped,
   616		}
   617		for _, evidence := range edge.relation.Evidence {
   618			step.Evidence = append(step.Evidence, Evidence{Kind: evidence.Kind, File: evidence.FilePath, StartLine: evidence.StartLine, EndLine: evidence.EndLine, Detail: evidence.Detail})
   619		}
   620		return step
   621	}
