   623	func blockingRelation(step Step) bool {
   624		if step.EvidenceClass != "confirmed" {
   625			return false
   626		}
   627		switch step.Relation {
   628		case "IMPORTS", "CALLS", "CONSTRUCTS", "ASYNC_CALLS", "USES_TYPE", "PARAM_TYPE", "RETURNS_TYPE",
   629			"READS_FIELD", "WRITES_FIELD", "ACCESSES", "DATA_FLOWS", "RESOURCE_DEPENDS_ON":
   630			return true
   631		default:
   632			return false
   633		}
