   636	func (index graphIndex) testTargets(left, right map[string]bool) []string {
   637		all := map[string]bool{}
   638		for id := range left {
   639			all[id] = true
   640		}
   641		for id := range right {
   642			all[id] = true
   643		}
   644		tests := map[string]bool{}
   645		for _, relation := range index.relations {
   646			if relation.Type != "TESTS" || !all[relation.FromID] && !all[relation.ToID] {
   647				continue
   648			}
   649			for _, id := range []string{relation.FromID, relation.ToID} {
   650				if endpoint, ok := index.endpoints[id]; ok && conventionalTestPath(endpoint.File) {
   651					tests[endpoint.File] = true
   652				}
   653			}
   654		}
   655		var result []string
