   663	func conventionalTestPath(path string) bool {
   664		lower := strings.ToLower(filepath.ToSlash(path))
   665		base := filepath.Base(lower)
   666		return strings.Contains(lower, "/test/") || strings.Contains(lower, "/tests/") ||
   667			strings.Contains(lower, "/__tests__/") || strings.HasSuffix(base, "_test.go") ||
